theorem IsCharacteristicVector.add_of_forall_even {k l : V → ℤ}
    (hk : P.IsCharacteristicVector k) (hl : ∀ v : V, Even (l v)) :
    P.IsCharacteristicVector fun v => k v + l v

theorem IsCharacteristicVector.even_sub {k l : V → ℤ}
    (hk : P.IsCharacteristicVector k) (hl : P.IsCharacteristicVector l) (v : V) :
    Even (k v - l v)

theorem IsCharacteristicVector.sub_modEq_zero {k l : V → ℤ}
    (hk : P.IsCharacteristicVector k) (hl : P.IsCharacteristicVector l) (v : V) :
    k v - l v ≡ 0 [ZMOD 2]

theorem IsCharacteristicVector.even_sub_canonical {k : V → ℤ}
    (hk : P.IsCharacteristicVector k) (v : V) :
    Even (k v - P.canonicalCharacteristic v)

irreducible_def characteristicUpperFaceExponent [Fintype V] (P : PlumbingGraph V)
    (k : P.characteristicVectors) (C : PlumbingCube V) {v : V}
    (hv : v ∈ C.directions) : ℕ

irreducible_def characteristicUpperFaceExponent [Fintype V] (P : PlumbingGraph V)
    (k : P.characteristicVectors) (C : PlumbingCube V) {v : V}
    (hv : v ∈ C.directions) : ℕ

def lowerFaceDirectionEquiv (C : PlumbingCube V) (v : V)
    (hv : v ∈ C.directions) :
    (C.lowerFace v hv).directions ≃ C.directions.erase v

def upperFaceDirectionEquiv (C : PlumbingCube V) (v : V)
    (hv : v ∈ C.directions) :
    (C.upperFace v hv).directions ≃ C.directions.erase v

def swapOffDiag (C : PlumbingCube V)
    (p : {p // p ∈ C.directions.offDiag}) :
    {p // p ∈ C.directions.offDiag}
